svg.script:
(function () {
  var svg = document.documentElement;
  var views = [[170, 0, 1100, 1210], [170, 1310, 1100, 740], [170, 2145, 1100, 495], [170, 2732, 1100, 588]];
  function go(n) {
    var v = views[n];
    svg.setAttribute('viewBox', v.join(' '));
    var c = svg.getElementById('view-clip-rect');
    c.setAttribute('y', v[1]); c.setAttribute('height', v[3]);
  }
  var els = svg.querySelectorAll('[data-go]');
  for (var i = 0; i < els.length; i++) {
    els[i].addEventListener('click', function (e) { go(+e.currentTarget.getAttribute('data-go')); });
  }
})();
